from __future__ import annotations

import json
from html import escape

from fastapi import APIRouter, Request
from fastapi.responses import HTMLResponse, RedirectResponse

from .branding import PRODUCT_FULL_NAME, TAGLINE
from .plans import AUTOMATION, BASIC_TIMELINE, MULTITRACK_DAW

router = APIRouter()


@router.get("/daw", response_class=HTMLResponse)
def daw_workspace(request: Request):
    member = getattr(request.state, "member", None)
    if not member:
        return RedirectResponse("/signin", status_code=303)
    if not member.plan.has(BASIC_TIMELINE):
        return RedirectResponse("/pricing", status_code=303)

    flags = {
        "multitrack": member.plan.has(MULTITRACK_DAW),
        "automation": member.plan.has(AUTOMATION),
    }
    page = r"""<!doctype html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Visual DAW — __PRODUCT__</title>
<style>
:root{--bg:#08050d;--panel:#140b1d;--panel2:#1e1029;--line:#50305d;--gold:#e9be61;--text:#fff;--muted:#c9bad1;--good:#78dda1;--bad:#ff8ea2;--trackhead:220px;--laneh:92px}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 20% 0,#351442 0,#120817 34%,#07040a 75%);color:var(--text);font-family:Inter,system-ui,sans-serif;overflow:hidden}button,input,select{font:inherit}.top{height:70px;padding:10px 15px;border-bottom:1px solid var(--line);background:#0b0610ee;display:flex;align-items:center;gap:10px;flex-wrap:wrap}.brand{min-width:230px}.brand b{color:var(--gold);font-size:.7rem;letter-spacing:.12em;text-transform:uppercase}.brand h1{font-size:1.05rem;margin:2px 0}.btn,button{border:1px solid var(--line);background:#24142e;color:#fff;border-radius:9px;padding:8px 11px;font-weight:800;cursor:pointer}.primary{background:linear-gradient(135deg,#f5d887,#bd8430);color:#180b18;border:0}.danger{background:#51202e}.pill{border:1px solid var(--line);border-radius:999px;padding:6px 10px;color:var(--gold);font-weight:800}select,input{background:#0a0610;color:#fff;border:1px solid var(--line);border-radius:8px;padding:8px}.app{height:calc(100vh - 70px);display:grid;grid-template-columns:1fr 310px}.main{min-width:0;display:grid;grid-template-rows:45px 1fr 118px}.toolbar{border-bottom:1px solid var(--line);background:#100817;padding:7px 10px;display:flex;align-items:center;gap:9px;overflow:auto}.timeline-shell{position:relative;overflow:auto;background:#09060e}.ruler-wrap{position:sticky;top:0;z-index:20;height:30px;background:#100917;border-bottom:1px solid #ffffff16;margin-left:var(--trackhead)}#ruler{display:block;height:30px}.track-row{height:var(--laneh);position:relative;border-bottom:1px solid #ffffff10;min-width:100%;background:linear-gradient(90deg,#0d0812,#0a070e)}.track-head{position:sticky;left:0;z-index:15;width:var(--trackhead);height:100%;background:#160d1e;border-right:1px solid var(--line);padding:8px;display:grid;grid-template-columns:1fr auto;gap:5px}.track-head h4{margin:0;font-size:.9rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.role{font-size:.68rem;color:var(--muted);text-transform:uppercase}.mixmini{grid-column:1/-1;display:grid;grid-template-columns:1fr 1fr auto auto;gap:4px;align-items:center}.mixmini input{min-width:0;width:100%;padding:4px}.mixmini button{padding:4px 7px}.lane{position:absolute;left:var(--trackhead);top:0;bottom:0}.clip{position:absolute;top:12px;height:66px;border:1px solid #8b5a99;border-radius:9px;background:linear-gradient(180deg,#4a225a,#26122f);overflow:hidden;cursor:grab;box-shadow:0 5px 18px #0007;user-select:none}.clip.selected{outline:2px solid var(--gold);border-color:var(--gold)}.clip canvas{position:absolute;inset:0;width:100%;height:100%;opacity:.85}.clip-label{position:relative;z-index:3;padding:5px 7px;font-size:.72rem;font-weight:850;text-shadow:0 1px 2px #000;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.clip small{position:absolute;z-index:3;left:7px;bottom:4px;color:#e9ddec;font-size:.63rem}.fade-in,.fade-out{position:absolute;top:0;bottom:0;z-index:4;pointer-events:none}.fade-in{left:0;border-right:1px dashed #ffe08a;background:linear-gradient(135deg,#ffe08a22,transparent 55%)}.fade-out{right:0;border-left:1px dashed #ffe08a;background:linear-gradient(225deg,#ffe08a22,transparent 55%)}#playhead{position:absolute;top:30px;bottom:0;width:1px;background:#ff5470;z-index:18;pointer-events:none;left:var(--trackhead)}#playhead:before{content:'';position:absolute;top:-5px;left:-5px;border-left:5px solid transparent;border-right:5px solid transparent;border-top:7px solid #ff5470}.bottom{border-top:1px solid var(--line);background:#100817;padding:9px 12px;display:grid;grid-template-columns:1fr 340px;gap:12px}.status{background:#08050b;border:1px solid #3e2749;border-radius:10px;padding:8px;overflow:auto;white-space:pre-wrap;font-size:.77rem;color:var(--muted)}audio{width:100%;height:34px}.side{border-left:1px solid var(--line);background:#100817;overflow:auto;padding:12px}.card{background:#170d20;border:1px solid var(--line);border-radius:14px;padding:12px;margin-bottom:11px}.card h3{margin:0 0 8px;color:var(--gold);font-size:.95rem}.field{margin:7px 0}.field label{display:block;font-size:.7rem;color:var(--muted);margin-bottom:3px}.field input,.field select{width:100%}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:7px}.muted{color:var(--muted);font-size:.76rem}.locked{opacity:.5}.automation-editor textarea{width:100%;min-height:90px;background:#09050d;color:#fff;border:1px solid var(--line);border-radius:8px;padding:8px}#empty{padding:40px;text-align:center;color:var(--muted)}@media(max-width:900px){body{overflow:auto}.app{height:auto;display:block}.main{height:760px}.side{border-left:0;border-top:1px solid var(--line)}.top{height:auto}.app{min-height:calc(100vh - 100px)}}
</style></head><body>
<div class="top"><div class="brand"><b>Elevate Souls Productions Presents</b><h1>ESP Live Sound Studio · Visual DAW</h1><span class="muted">Aura · __TAGLINE__</span></div><select id="projectSelect"></select><button onclick="loadProject()">Open</button><span class="pill">__PLAN__</span><a class="btn" href="/studio">Studio</a><a class="btn" href="/production-suite">Production Suite</a><a class="btn" href="/history">History / Undo</a></div>
<div class="app"><section class="main"><div class="toolbar"><button id="playBtn" onclick="togglePlayback()">▶ Play Bounce</button><button onclick="renderMix()" class="primary">Render DAW Mix</button><label>Zoom <input id="zoom" type="range" min="15" max="180" value="55" oninput="setZoom(this.value)"></label><label><input id="snap" type="checkbox" checked> Snap 1/16</label><span id="timeReadout" class="pill">0:00.000</span><button onclick="setLoopStart()">Loop Start</button><button onclick="setLoopEnd()">Loop End</button><button onclick="clearLoop()">Clear Loop</button><span id="loopReadout" class="muted"></span></div><div id="timeline" class="timeline-shell"><div class="ruler-wrap"><canvas id="ruler"></canvas></div><div id="tracks"></div><div id="playhead"></div><div id="empty">Select a project with a DAW session, or initialize one from an audio asset.</div></div><div class="bottom"><div id="status" class="status">Visual DAW ready.</div><div><audio id="mixPlayer" controls></audio><div class="muted">Session bounce is real waveform audio; MIDI/control clips are never rendered as Final Master.</div></div></div></section>
<aside class="side"><div class="card"><h3>Session</h3><div id="sessionInfo" class="muted">No project loaded.</div><div class="field"><label>Initialize from audio asset</label><select id="assetSelect"></select></div><div class="field"><label>Role</label><select id="assetRole"><option>vocals</option><option>guitar</option><option>piano</option><option>keyboard</option><option>bass</option><option>drums</option><option>synth</option><option>strings</option><option>other</option></select></div><button onclick="initFromAsset()">Initialize / Import First Lane</button><button id="multiImport" onclick="importTrack()" style="display:none">+ Import Pro Track</button></div>
<div class="card"><h3>Selected Clip</h3><div id="noClip" class="muted">Click a clip to edit it.</div><div id="clipEditor" style="display:none"><div class="field"><label>Name</label><div id="clipName"></div></div><div class="grid2"><div class="field"><label>Timeline Start</label><input id="clipStart" type="number" step="0.001"></div><div class="field"><label>Duration</label><input id="clipDuration" type="number" step="0.001"></div><div class="field"><label>Source Offset</label><input id="clipOffset" type="number" step="0.001"></div><div class="field"><label>Clip Gain dB</label><input id="clipGain" type="number" step="0.1"></div><div class="field"><label>Fade In</label><input id="fadeIn" type="number" step="0.01"></div><div class="field"><label>Fade Out</label><input id="fadeOut" type="number" step="0.01"></div></div><button onclick="applyTrim()">Apply Trim / Position</button><button onclick="applyGainFades()">Apply Gain + Fades</button><button onclick="splitAtPlayhead()">Split at Playhead</button><button class="danger" onclick="deleteSelected()">Delete Clip</button></div></div>
<div id="automationCard" class="card automation-editor" style="display:none"><h3>Pro Automation</h3><p class="muted">Drawn UI comes next; this editor already writes validated volume/pan automation points.</p><select id="automationParam"><option value="volume_db">Volume dB</option><option value="pan">Pan</option></select><textarea id="automationPoints">[{"time":0,"value":0},{"time":8,"value":-2}]</textarea><button onclick="saveAutomation()">Save Automation to Selected Track</button></div>
</aside></div>
<script>
const FLAGS=__FLAGS__;let projects=[],session=null,currentProject=null,selectedClip=null,selectedTrack=null,zoom=55,playheadTime=0,drag=null,waveCache=new Map();
const $=id=>document.getElementById(id);function status(v,good=true){$('status').textContent=typeof v==='string'?v:JSON.stringify(v,null,2);$('status').style.color=good?'var(--muted)':'var(--bad)'}
async function api(url,opt={}){const r=await fetch(url,{credentials:'same-origin',...opt});let b;try{b=await r.json()}catch{b=await r.text()}if(!r.ok)throw new Error(typeof b==='string'?b:(b.detail||JSON.stringify(b)));return b}
function fmt(t){t=Math.max(0,Number(t)||0);const m=Math.floor(t/60),s=t-m*60;return m+':'+s.toFixed(3).padStart(6,'0')}
function enc(v){return encodeURIComponent(v)}
async function boot(){try{projects=await api('/projects');$('projectSelect').innerHTML=projects.map(p=>`<option value="${escapeHtml(p.name)}">${escapeHtml(p.name)}</option>`).join('');if(FLAGS.multitrack)$('multiImport').style.display='inline-block';if(FLAGS.automation)$('automationCard').style.display='block';const q=new URLSearchParams(location.search).get('project');if(q&&projects.some(p=>p.name===q))$('projectSelect').value=q;if(projects.length)await loadProject()}catch(e){status(e.message,false)}}
async function loadProject(){currentProject=$('projectSelect').value;if(!currentProject)return;selectedClip=null;selectedTrack=null;waveCache.clear();await loadAssets();try{session=await api(`/projects/${enc(currentProject)}/daw/session`);render()}catch(e){session=null;$('tracks').innerHTML='';$('empty').style.display='block';$('sessionInfo').textContent='No DAW session yet. Choose an audio asset below to initialize the timeline.';status(e.message,false)}}
async function loadAssets(){try{const rows=await api(`/projects/${enc(currentProject)}/assets`);$('assetSelect').innerHTML=rows.filter(x=>x.kind==='audio').map(x=>`<option value="${escapeHtml(x.id)}">${escapeHtml(x.name)}</option>`).join('')}catch{$('assetSelect').innerHTML=''}}
async function initFromAsset(){const id=$('assetSelect').value;if(!id)return status('Choose an audio asset first.',false);try{session=await api(`/projects/${enc(currentProject)}/daw/init`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({asset_id:id,role:$('assetRole').value})});render();status('Timeline initialized.')}catch(e){status(e.message,false)}}
async function importTrack(){const id=$('assetSelect').value;if(!id)return;try{session=await api(`/projects/${enc(currentProject)}/daw/import/${enc(id)}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({asset_id:id,role:$('assetRole').value})});render();status('Pro multitrack lane imported.')}catch(e){status(e.message,false)}}
function escapeHtml(s){return String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function timelineWidth(){return Math.max(1000,(Math.max(session?.duration||0,60)+12)*zoom)}
function setZoom(v){zoom=Number(v);if(session)render()}
function snapTime(t){if(!$('snap').checked||!session)return Math.max(0,t);const beat=60/(session.bpm||120),grid=beat/4;return Math.max(0,Math.round(t/grid)*grid)}
function render(){if(!session)return;$('empty').style.display='none';$('sessionInfo').textContent=`${session.name} · ${session.bpm} BPM · ${session.key||'Key not set'} · ${session.meter} · ${session.sample_rate} Hz`;$('loopReadout').textContent=session.loop_start==null?'':`Loop ${fmt(session.loop_start)} → ${fmt(session.loop_end)}`;const width=timelineWidth();drawRuler(width);const root=$('tracks');root.innerHTML='';for(const track of session.tracks.filter(t=>t.role!=='master'))root.appendChild(trackRow(track,width));updatePlayhead();refreshInspector()}
function trackRow(track,width){const row=document.createElement('div');row.className='track-row';row.style.width=(width+220)+'px';const head=document.createElement('div');head.className='track-head';head.innerHTML=`<div><h4>${escapeHtml(track.name)}</h4><div class="role">${escapeHtml(track.role)}</div></div><span class="pill">${track.effect_count} FX</span><div class="mixmini"><input title="Volume dB" type="number" step="0.1" value="${track.volume_db}"><input title="Pan -1..1" type="number" step="0.05" min="-1" max="1" value="${track.pan}"><button>${track.mute?'M✓':'M'}</button><button>${track.solo?'S✓':'S'}</button></div>`;const mix=head.querySelectorAll('.mixmini input'),buttons=head.querySelectorAll('.mixmini button');mix[0].onchange=()=>saveTrackMix(track,{volume_db:Number(mix[0].value)});mix[1].onchange=()=>saveTrackMix(track,{pan:Number(mix[1].value)});buttons[0].onclick=()=>saveTrackMix(track,{mute:!track.mute});buttons[1].onclick=()=>saveTrackMix(track,{solo:!track.solo});row.appendChild(head);const lane=document.createElement('div');lane.className='lane';lane.style.width=width+'px';lane.onclick=e=>{if(e.target===lane){const rect=lane.getBoundingClientRect();setPlayhead((e.clientX-rect.left)/zoom)}};for(const clip of track.clips.filter(c=>c.kind==='audio'))lane.appendChild(clipEl(track,clip));row.appendChild(lane);return row}
function clipEl(track,clip){const el=document.createElement('div');el.className='clip'+(selectedClip?.id===clip.id?' selected':'');el.dataset.id=clip.id;el.style.left=(clip.start*zoom)+'px';el.style.width=Math.max(22,clip.duration*zoom)+'px';el.innerHTML=`<canvas></canvas><div class="fade-in"></div><div class="fade-out"></div><div class="clip-label">${escapeHtml(clip.name)}</div><small>Take ${clip.take_lane+1} · ${clip.gain_db.toFixed(1)} dB</small>`;el.querySelector('.fade-in').style.width=(Math.min(clip.fade_in,clip.duration)*zoom)+'px';el.querySelector('.fade-out').style.width=(Math.min(clip.fade_out,clip.duration)*zoom)+'px';el.onclick=e=>{e.stopPropagation();selectedClip=clip;selectedTrack=track;render();};el.onpointerdown=e=>{if(e.button!==0)return;drag={el,clip,track,startX:e.clientX,orig:clip.start};el.setPointerCapture(e.pointerId)};el.onpointermove=e=>{if(!drag||drag.el!==el)return;const next=snapTime(drag.orig+(e.clientX-drag.startX)/zoom);el.style.left=(next*zoom)+'px';$('timeReadout').textContent=fmt(next)};el.onpointerup=async e=>{if(!drag||drag.el!==el)return;const next=snapTime(drag.orig+(e.clientX-drag.startX)/zoom);drag=null;try{await api(`/projects/${enc(currentProject)}/daw/clips/${enc(clip.id)}/move`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({start:next})});await reloadSession()}catch(err){status(err.message,false)}};drawWave(clip,el.querySelector('canvas'));return el}
async function drawWave(clip,canvas){try{let data=waveCache.get(clip.id);if(!data){data=await api(`/projects/${enc(currentProject)}/daw/clips/${enc(clip.id)}/waveform?points=700`);waveCache.set(clip.id,data)}const dpr=devicePixelRatio||1,w=Math.max(10,canvas.clientWidth),h=Math.max(10,canvas.clientHeight);canvas.width=w*dpr;canvas.height=h*dpr;const c=canvas.getContext('2d');c.scale(dpr,dpr);c.strokeStyle='#f4c968';c.globalAlpha=.85;c.beginPath();const peaks=data.peaks||[];for(let i=0;i<peaks.length;i++){const x=(i/(Math.max(1,peaks.length-1)))*w,mid=h/2;c.moveTo(x,mid-peaks[i][1]*mid*.88);c.lineTo(x,mid-peaks[i][0]*mid*.88)}c.stroke()}catch{}}
function drawRuler(width){const c=$('ruler'),dpr=devicePixelRatio||1;c.style.width=width+'px';c.width=width*dpr;c.height=30*dpr;const x=c.getContext('2d');x.scale(dpr,dpr);x.clearRect(0,0,width,30);x.fillStyle='#c9bad1';x.strokeStyle='#50305d';x.font='10px system-ui';const major=zoom>=80?1:zoom>=35?5:10;for(let t=0;t<width/zoom;t+=major){const p=t*zoom;x.beginPath();x.moveTo(p,15);x.lineTo(p,30);x.stroke();x.fillText(fmt(t).replace('.000',''),p+3,11)}c.onclick=e=>{const r=c.getBoundingClientRect();setPlayhead((e.clientX-r.left)/zoom)}}
function setPlayhead(t){playheadTime=snapTime(t);$('timeReadout').textContent=fmt(playheadTime);updatePlayhead()}
function updatePlayhead(){$('playhead').style.left=(220+playheadTime*zoom)+'px'}
function refreshInspector(){if(!selectedClip){$('noClip').style.display='block';$('clipEditor').style.display='none';return}$('noClip').style.display='none';$('clipEditor').style.display='block';$('clipName').textContent=selectedClip.name;$('clipStart').value=selectedClip.start;$('clipDuration').value=selectedClip.duration;$('clipOffset').value=selectedClip.source_offset;$('clipGain').value=selectedClip.gain_db;$('fadeIn').value=selectedClip.fade_in;$('fadeOut').value=selectedClip.fade_out}
async function reloadSession(){session=await api(`/projects/${enc(currentProject)}/daw/session`);if(selectedClip){const id=selectedClip.id;selectedClip=null;for(const t of session.tracks){const c=t.clips.find(x=>x.id===id);if(c){selectedClip=c;selectedTrack=t;break}}}render()}
async function applyTrim(){if(!selectedClip)return;try{await api(`/projects/${enc(currentProject)}/daw/clips/${enc(selectedClip.id)}/trim`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({start:Number($('clipStart').value),duration:Number($('clipDuration').value),source_offset:Number($('clipOffset').value)})});waveCache.delete(selectedClip.id);await reloadSession();status('Clip trim saved non-destructively.')}catch(e){status(e.message,false)}}
async function applyGainFades(){if(!selectedClip)return;try{await api(`/projects/${enc(currentProject)}/daw/clips/${enc(selectedClip.id)}/gain`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({gain_db:Number($('clipGain').value)})});await api(`/projects/${enc(currentProject)}/daw/clips/${enc(selectedClip.id)}/fades`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({fade_in:Number($('fadeIn').value),fade_out:Number($('fadeOut').value)})});await reloadSession();status('Clip gain and fades saved.')}catch(e){status(e.message,false)}}
async function splitAtPlayhead(){if(!selectedClip)return;try{await api(`/projects/${enc(currentProject)}/daw/clips/${enc(selectedClip.id)}/split`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({time:playheadTime})});selectedClip=null;waveCache.clear();await reloadSession();status('Clip split at '+fmt(playheadTime)+'.')}catch(e){status(e.message,false)}}
async function deleteSelected(){if(!selectedClip||!confirm('Delete this clip from the session? The source audio remains untouched.'))return;try{await api(`/projects/${enc(currentProject)}/daw/clips/${enc(selectedClip.id)}`,{method:'DELETE'});selectedClip=null;await reloadSession();status('Clip removed from timeline; source audio was not deleted.')}catch(e){status(e.message,false)}}
async function saveTrackMix(track,patch){try{await api(`/projects/${enc(currentProject)}/daw/tracks/${enc(track.id)}/mix`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(patch)});await reloadSession()}catch(e){status(e.message,false)}}
async function setLoopStart(){if(!session)return;const end=session.loop_end!=null&&session.loop_end>playheadTime?session.loop_end:playheadTime+4*(60/session.bpm);await setLoop(playheadTime,end)}async function setLoopEnd(){if(!session)return;const start=session.loop_start!=null&&session.loop_start<playheadTime?session.loop_start:Math.max(0,playheadTime-4*(60/session.bpm));await setLoop(start,playheadTime)}async function clearLoop(){await setLoop(null,null)}async function setLoop(start,end){try{await api(`/projects/${enc(currentProject)}/daw/loop`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({start,end})});await reloadSession()}catch(e){status(e.message,false)}}
async function saveAutomation(){if(!selectedTrack)return status('Select a clip on the track you want to automate.',false);try{const points=JSON.parse($('automationPoints').value);await api(`/projects/${enc(currentProject)}/daw/tracks/${enc(selectedTrack.id)}/automation`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({parameter:$('automationParam').value,points})});await reloadSession();status('Automation lane saved.')}catch(e){status(e.message,false)}}
async function renderMix(){if(!currentProject)return;try{status('Rendering real-audio DAW mix…');const r=await api(`/projects/${enc(currentProject)}/daw/render`,{method:'POST'});$('mixPlayer').src=r.stream_url+'?v='+Date.now();$('mixPlayer').load();status(r)}catch(e){status(e.message,false)}}
function togglePlayback(){const p=$('mixPlayer');if(!p.src)return renderMix();if(p.paused){p.play();$('playBtn').textContent='⏸ Pause'}else{p.pause();$('playBtn').textContent='▶ Play Bounce'}}
$('mixPlayer').ontimeupdate=()=>{if(!$('mixPlayer').paused)setPlayhead($('mixPlayer').currentTime)};$('mixPlayer').onended=()=>{$('playBtn').textContent='▶ Play Bounce'};
boot();
</script></body></html>"""
    return HTMLResponse(
        page.replace("__PRODUCT__", escape(PRODUCT_FULL_NAME))
        .replace("__TAGLINE__", escape(TAGLINE))
        .replace("__PLAN__", escape(member.plan.name))
        .replace("__FLAGS__", json.dumps(flags))
    )
